INSERT INTO trucker.item_pg
  (id, item_id, rec_start_date, rec_end_date, item_desc, current_price,
   wholesale_cost, brand_id, brand, class_id, i_class, category_id, category,
   manufact_id, manufact, i_size, formulation, color, units, container,
   manager_id, product_name, deleted)
SELECT r.id,
       r.item_id,
       r.rec_start_date,
       r.rec_end_date,
       r.item_desc,
       r.current_price::float8,
       r.wholesale_cost::float8,
       r.brand_id::int,
       r.brand,
       r.class_id::int,
       r.i_class,
       r.category_id::int,
       r.category,
       r.manufact_id::int,
       r.manufact,
       r.i_size,
       r.formulation,
       r.color,
       r.units,
       r.container,
       r.manager_id::int,
       r.product_name,
       {{ .operation | eq "delete" }}
FROM {{ .rows }}
ON CONFLICT (id) DO UPDATE SET
  item_id        = EXCLUDED.item_id,
  rec_start_date = EXCLUDED.rec_start_date,
  rec_end_date   = EXCLUDED.rec_end_date,
  item_desc      = EXCLUDED.item_desc,
  current_price  = EXCLUDED.current_price,
  wholesale_cost = EXCLUDED.wholesale_cost,
  brand_id       = EXCLUDED.brand_id,
  brand          = EXCLUDED.brand,
  class_id       = EXCLUDED.class_id,
  i_class        = EXCLUDED.i_class,
  category_id    = EXCLUDED.category_id,
  category       = EXCLUDED.category,
  manufact_id    = EXCLUDED.manufact_id,
  manufact       = EXCLUDED.manufact,
  i_size         = EXCLUDED.i_size,
  formulation    = EXCLUDED.formulation,
  color          = EXCLUDED.color,
  units          = EXCLUDED.units,
  container      = EXCLUDED.container,
  manager_id     = EXCLUDED.manager_id,
  product_name   = EXCLUDED.product_name,
  deleted        = EXCLUDED.deleted
